head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.btn_browserPopup_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "browserPopup1",
        popupName: "팝업-browserPopup",
        width: 500,
        height: 400,
        type: "browserPopup",
        modal: false,
        useModalStack: true //browserPopup 은 useModalStack : false 를 줘야 에러 나지 않음..... (2022-02-15) 			
    };
    $p.openPopup("popup_modal_wrong_work_WESD-862_(WSQ-4840)_pop.xml", options);
};
scwin.btn_wframePopup_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "wframePopup1",
        popupName: "팝업-wframePopup",
        width: 500,
        height: 400,
        type: "wframePopup",
        modal: true,
        useModalStack: true //wframePopup 은 현재 useModalStack : true 로 default 셋팅 ( true로 해야 alert, confirm 등이 최상위로 올라옴 ) 
    };
    $p.openPopup("popup_modal_wrong_work_WESD-862_(WSQ-4840)_pop.xml", options);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //22년 1월 25일 버전은 잘되긴함 
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
